// Board ring logic: generated by OpenRouter (nvidia/nemotron-3-ultra-550b-a55b:free),
// then extended with free-egg handling and result messages. Pure logic, no DOM/Three,
// so it ports to a Luau ModuleScript almost line for line.

export const CHANCE_TABLE = [
  { weight: 20, kind: 'gain', amount: 15, text: '행운의 화약! +15' },
  { weight: 14, kind: 'gain', amount: 30, text: '떨어진 화약 자루! +30' },
  { weight: 18, kind: 'lose', amount: 10, text: '화약 주머니가 터졌다! -10' },
  { weight: 16, kind: 'teleport', amount: 3, text: '바람길을 타고 3칸 앞으로!' },
  { weight: 16, kind: 'teleport', amount: -2, text: '발을 헛디뎌 2칸 뒤로!' },
  { weight: 16, kind: 'freeEgg', amount: 0, text: '누군가 알을 두고 갔다! 무료 알!' },
];

export class BoardGame {
  constructor({ cells, diceSides = 6 }) {
    this.cells = cells;
    this.diceSides = diceSides;
    this.position = 0;
    this.laps = 0;
    this.pendingEgg = false;
    this.moveHistory = [];
  }

  roll(rng = Math.random) {
    return Math.floor(rng() * this.diceSides) + 1;
  }

  /** Returns every index passed through, landing included. */
  move(steps) {
    const path = [];
    for (let i = 0; i < steps; i++) {
      this.position++;
      if (this.position >= this.cells.length) {
        this.position = 0;
        this.laps++;
      }
      path.push(this.position);
    }
    this.moveHistory.push(this.position);
    return path;
  }

  jumpTo(index) {
    const n = this.cells.length;
    this.position = ((index % n) + n) % n;
    return this.position;
  }

  landingCell() {
    return this.cells[this.position];
  }

  resolve(cell, state, rng = Math.random) {
    switch (cell.type) {
      case 'gunpowder':
        return { kind: 'gunpowder', gunpowder: cell.value, title: cell.nameKo, message: `화약 +${cell.value}` };
      case 'jackpot':
        return { kind: 'jackpot', gunpowder: cell.value, title: cell.nameKo, message: `잭팟! 화약 +${cell.value}` };
      case 'risk':
        return { kind: 'risk', gunpowder: -cell.value, title: cell.nameKo, message: `화약 -${cell.value}` };
      case 'egg':
        if (state.gunpowder >= cell.cost) {
          return { kind: 'egg', gunpowder: -cell.cost, needsEggCost: false, title: cell.nameKo, message: `알 구매 (-${cell.cost} 화약)` };
        }
        return { kind: 'egg-blocked', gunpowder: 0, needsEggCost: true, title: cell.nameKo, message: '화약이 부족해 알을 살 수 없다' };
      case 'buff':
        return { kind: 'buff', buffPoints: cell.value, title: cell.nameKo, message: `영구 버프 +${cell.value}` };
      case 'mutation':
        return { kind: 'mutation', captures: cell.value, title: cell.nameKo, message: `다음 포획 ${cell.value}회 변이 확률 UP` };
      case 'chance': {
        const total = CHANCE_TABLE.reduce((sum, e) => sum + e.weight, 0);
        let r = rng() * total;
        let picked = CHANCE_TABLE[CHANCE_TABLE.length - 1];
        for (const entry of CHANCE_TABLE) {
          if (r < entry.weight) { picked = entry; break; }
          r -= entry.weight;
        }
        return {
          kind: 'chance',
          effect: { type: picked.kind, amount: picked.amount },
          title: '찬스 카드',
          message: picked.text,
        };
      }
      case 'start':
        return { kind: 'start', gunpowder: 10, title: cell.nameKo, message: '한 바퀴 완주! 화약 +10' };
      default:
        return { kind: 'none', gunpowder: 0, title: cell.nameKo, message: '' };
    }
  }

  /** Mutates a plain state bag; returns the new gunpowder. */
  applyEffect(effect, state) {
    switch (effect.kind) {
      case 'gunpowder':
      case 'jackpot':
      case 'risk':
      case 'egg':
      case 'start':
        state.gunpowder = Math.max(0, state.gunpowder + (effect.gunpowder || 0));
        break;
      case 'buff':
        state.buffPoints = (state.buffPoints || 0) + (effect.buffPoints || 0);
        break;
      case 'mutation':
        state.pendingMutation = (state.pendingMutation || 0) + effect.captures;
        break;
      case 'chance': {
        const sub = effect.effect;
        if (sub.type === 'gain') state.gunpowder += sub.amount;
        else if (sub.type === 'lose') state.gunpowder = Math.max(0, state.gunpowder - sub.amount);
        else if (sub.type === 'teleport') state.position = (state.position + sub.amount + this.cells.length) % this.cells.length;
        break;
      }
      default:
        break;
    }
    if (effect.kind !== 'egg') state.lastEggFree = false;
    return state.gunpowder;
  }
}

export default BoardGame;
